// SUITE_NAME.ini: one [section] per module, key=value, # comments.
// The compiled defaults are the developer's; a player who has no ini (or an old one without a new key) gets the
// standard preset instead (preset_standard.inc, generated by tools/gen_ini.py inc; else a deleted ini would mean the
// developer's wheel buttons, experimental lane steering and big csv traces). A missing file is written with those values
// and the help lines. Values are checked for sanity (finite, within bounds) and the effective values go into the log.
#include "suite.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

// [core]: settings of the suite itself (no code of its own).
static float p_log_level, p_log_max_mb, p_csv_max_mb, p_incident_mb;
